SELECT round(avg(v),0) AS avg_inv_value, min(v) AS min_inv, max(v) AS max_inv FROM (
  SELECT b.date, sum(b.book_on_hand_close*p.cost_inr) AS v
  FROM store.inventory_book b JOIN store.products p ON p.sku=b.sku
  WHERE b.date BETWEEN '2026-06-01' AND '2026-06-28' GROUP BY b.date
) t;

SELECT sku, gtin, name, pack, flow, price_inr, cost_inr
FROM store.products
ORDER BY sku;

