sql_calls.sql:
SELECT sku, name, pack, price_inr, cost_inr, flow
FROM store.products
ORDER BY sku;

SELECT audit_ts, sku, status
FROM store.shelf_audits
ORDER BY audit_ts, sku;

SELECT sku, name, pack, flow, price_inr, cost_inr
FROM store.products
WHERE lower(name) LIKE '%atta%' OR lower(pack) LIKE '%5%';

SELECT sum(units_sold) AS units_june, sum(revenue_inr) AS revenue_june
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT audit_ts::date AS day, status, count(*) AS audits
FROM store.shelf_audits
GROUP BY 1,2 ORDER BY 1,2;

SELECT date, units_sold, revenue_inr FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date < '2026-07-01'
ORDER BY date;

SELECT date, book_on_hand_close FROM store.inventory_book
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date < '2026-07-01'
ORDER BY date;

SELECT count(DISTINCT bill_id) AS bills
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT date_trunc('month', bill_ts) AS m, count(*) AS rows, count(DISTINCT bill_id) AS bills
FROM store.pos_lines
GROUP BY 1 ORDER BY 1;

SELECT * FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date < '2026-07-01'
ORDER BY settlement_date;

SELECT count(*) AS shipments, sum(pallets) AS pallets_declared
FROM warehouse.shipments
WHERE dispatched_ts >= '2026-06-01' AND dispatched_ts < '2026-07-01';
